CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Analysts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Analyst" character varying(120) NOT NULL,
    "Email" character varying(150),
    "Signature" text,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Analysts" PRIMARY KEY ("Id")
);

CREATE TABLE "Cliente" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Cliente" text NOT NULL,
    "Endereco" text,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "LastUpdate" timestamp without time zone,
    CONSTRAINT "PK_Cliente" PRIMARY KEY ("Id")
);

CREATE TABLE "Controle_Eleb" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "OP_ELEB" text,
    "OP_Digicon" text,
    "PO_ELEB" text,
    "COD_ELEB" text,
    "Part_Number" text,
    "Valor_Peca" text,
    "Analise_PO" text,
    "Revisao_Desenho" text,
    "Qtd_Saldo" text,
    "Qtd_Lote" text,
    "Qtd_Saldo1" text,
    "Data_Envio_para_ELEB" timestamp without time zone,
    "NF_Faturada" text,
    "Decapagem" text,
    "SN_Decap" text,
    "CD" text,
    "SN_Peca" text,
    "Cliente" text,
    "Situacao" text,
    "Lote_ELEB" text,
    "Num_Certificado" text,
    "UpdateBy" text,
    CONSTRAINT "PK_Controle_Eleb" PRIMARY KEY ("ID")
);

CREATE TABLE "History_PartNumber" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PartNumberId" integer NOT NULL,
    "Changes" text,
    "Observation" text,
    "ChangedBy" character varying(150) NOT NULL,
    "ChangedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_History_PartNumber" PRIMARY KEY ("Id")
);

CREATE TABLE "History_SpecialProcess" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SpecialProcessId" integer NOT NULL,
    "Changes" text,
    "Observation" text,
    "ChangedBy" character varying(150) NOT NULL,
    "ChangedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_History_SpecialProcess" PRIMARY KEY ("Id")
);

CREATE TABLE login_certification (
    username character varying(150) NOT NULL,
    email character varying(255) NOT NULL,
    password character varying(512) NOT NULL,
    salt character varying(512) NOT NULL,
    type character varying(50),
    image text,
    CONSTRAINT "PK_login_certification" PRIMARY KEY (username)
);

CREATE TABLE login_module_permissions (
    username character varying(150) NOT NULL,
    modulekey character varying(150) NOT NULL,
    canview boolean NOT NULL DEFAULT TRUE,
    canedit boolean NOT NULL DEFAULT FALSE,
    updatedat timestamp without time zone NOT NULL,
    CONSTRAINT "PK_login_module_permissions" PRIMARY KEY (username, modulekey)
);

CREATE TABLE login_password_resets (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    tokenhash character varying(64) NOT NULL,
    username character varying(150) NOT NULL,
    email character varying(255) NOT NULL,
    createdat timestamp without time zone NOT NULL,
    expiresat timestamp without time zone NOT NULL,
    usedat timestamp without time zone,
    CONSTRAINT "PK_login_password_resets" PRIMARY KEY (id)
);

CREATE TABLE login_sessions (
    sessionid uuid NOT NULL,
    username character varying(150) NOT NULL,
    email character varying(255),
    createdat timestamp without time zone NOT NULL,
    lastseen timestamp without time zone NOT NULL,
    revokedat timestamp without time zone,
    ipaddress character varying(64),
    useragent character varying(256),
    CONSTRAINT "PK_login_sessions" PRIMARY KEY (sessionid)
);

CREATE TABLE "OperationProcess" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "OperationQuantity" text NOT NULL,
    "OperationDescription" text NOT NULL,
    "IsActivated" boolean NOT NULL,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_OperationProcess" PRIMARY KEY ("Id")
);

CREATE TABLE "Parameters" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PartNumber" character varying(50) NOT NULL,
    "Processo" character varying(50) NOT NULL,
    "Norma" character varying(50) NOT NULL,
    "NormaRevision" character varying(10),
    "Parameter" character varying(100) NOT NULL,
    "Condition" character varying(100),
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Parameters" PRIMARY KEY ("Id")
);

CREATE TABLE "PartNumbers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PartNumber" text NOT NULL,
    "Descricao" text NOT NULL,
    "Revision" text,
    "DrawingRevision" character varying(50),
    "ClienteId" integer,
    "ClienteNome" character varying(200),
    "IsActive" boolean NOT NULL,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdated" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_PartNumbers" PRIMARY KEY ("Id")
);

CREATE TABLE "ProductConformityCertificates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CertificateNumber" text NOT NULL,
    "PartNumberId" integer,
    "PartNumber" text NOT NULL,
    "PartNumberDescription" text,
    "PartNumberRevision" text,
    "LotNumber" text,
    "Quantity" text,
    "CustomerPO" text,
    "Type" text,
    "SerialNumber" text,
    "InspectedAccording" text,
    "AnalystId" integer,
    "AnalystName" text,
    "DocumentNumber" text,
    "DocumentRevision" text,
    "DocumentDate" timestamp without time zone NOT NULL,
    "CustomerId" integer,
    "CustomerName" text,
    "CustomerAddress" text,
    "EmissionDate" timestamp without time zone NOT NULL,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ProductConformityCertificates" PRIMARY KEY ("Id")
);

CREATE TABLE "ProductDocumentControls" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DocumentNumber" text NOT NULL,
    "DocumentRevision" text NOT NULL,
    "DocumentDate" timestamp without time zone NOT NULL,
    "InspectedAccording" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
