CREATE TABLE "SpecialProcess" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SpecialProcess" character varying(50) NOT NULL,
    "Specification" character varying(20),
    "Revision" character varying(10),
    "Comment" text,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_SpecialProcess" PRIMARY KEY ("Id")
);

CREATE TABLE "SpecialProcessCertificates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CertificateCode" character varying(15) NOT NULL,
    "ClienteId" integer,
    "ClienteNome" character varying(200),
    "SpecialProcessId" integer,
    "SpecialProcess" character varying(120),
    "Norma" character varying(150),
    "PartNumber" character varying(100),
    "EmissionDate" timestamp without time zone NOT NULL,
    "Quantity" numeric(18,2) NOT NULL,
    "LotNumber" character varying(120),
    "PurchasingOrder" character varying(120),
    "Item" character varying(80),
    "HardnessFound" character varying(120),
    "HeatTreatLot" character varying(120),
    "AnalystId" integer,
    "AnalystName" character varying(150),
    "Observations" text,
    "CreateBy" text,
    "UpdateBy" text,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdate" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_SpecialProcessCertificates" PRIMARY KEY ("Id")
);

CREATE TABLE "TechnicalStandards" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Cliente" text NOT NULL,
    "Processo" text NOT NULL,
    "Norma" text NOT NULL,
    "Revision" text,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdated" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_TechnicalStandards" PRIMARY KEY ("Id")
);

CREATE TABLE "AnalystsCertificate" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Certificate" integer NOT NULL,
    "IsDefault" boolean NOT NULL,
    "AnalystsId" integer NOT NULL,
    "CreateBy" text NOT NULL,
    "UpdateBy" text NOT NULL,
    "CreateDate" timestamp without time zone NOT NULL,
    "LastUpdated" timestamp without time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_AnalystsCertificate" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AnalystsCertificate_Analysts_AnalystsId" FOREIGN KEY ("AnalystsId") REFERENCES "Analysts" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_AnalystsCertificate_AnalystsId" ON "AnalystsCertificate" ("AnalystsId");

CREATE UNIQUE INDEX "IX_AnalystsCertificate_Certificate_IsDefault" ON "AnalystsCertificate" ("Certificate", "IsDefault") WHERE "IsDeleted" = FALSE AND "IsDefault" = TRUE;

CREATE INDEX "IX_History_PartNumber_PartNumberId" ON "History_PartNumber" ("PartNumberId");

CREATE INDEX "IX_History_SpecialProcess_SpecialProcessId" ON "History_SpecialProcess" ("SpecialProcessId");

CREATE UNIQUE INDEX "IX_login_certification_email" ON login_certification (email);

CREATE INDEX "IX_login_module_permissions_username" ON login_module_permissions (username);

CREATE UNIQUE INDEX "IX_login_password_resets_tokenhash" ON login_password_resets (tokenhash);

CREATE INDEX "IX_login_password_resets_username_email" ON login_password_resets (username, email);

CREATE INDEX "IX_login_sessions_lastseen" ON login_sessions (lastseen);

CREATE INDEX "IX_login_sessions_username" ON login_sessions (username);

CREATE UNIQUE INDEX "IX_PurchaseOrders_PONumber_Item_ClienteId" ON "PurchaseOrders" ("PONumber", "Item", "ClienteId") WHERE "IsDeleted" = FALSE;

CREATE UNIQUE INDEX "IX_ShippingLabelPrintSettings_Username" ON "ShippingLabelPrintSettings" ("Username");

